import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from common import SqlSet
S = SqlSet("stocks", ["tickers", "prices"])
p = S.p
B = SqlSet("bank", ["customers", "accounts", "transactions"])
E = SqlSet("ecommerce", ["customers", "products", "orders", "order_items"])
M = SqlSet("movies", ["directors", "movies", "reviews"])
S.items  # stocks set is the module-level S; extra sets are merged below

p("Best single-day gain per ticker", "H", "window-functions", "For each ticker find the trading day with the largest close-to-previous-close percentage gain. Show symbol, trade_date, gain_pct (rounded to 2 decimals).", ["`LAG(close)` per symbol, then rank gains per symbol."],
  "WITH g AS (SELECT symbol, trade_date, 100.0 * (close - LAG(close) OVER (PARTITION BY symbol ORDER BY trade_date)) / LAG(close) OVER (PARTITION BY symbol ORDER BY trade_date) AS gain FROM prices), r AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY symbol ORDER BY gain DESC, trade_date) AS rn FROM g WHERE gain IS NOT NULL) SELECT symbol, trade_date, ROUND(gain, 2) AS gain_pct FROM r WHERE rn = 1;")
p("Three-day moving average crossover", "H", "window-functions", "Show the days where a ticker's close was above its 3-day moving average (including the current day) but the previous day it was below its own 3-day average. Show symbol and trade_date, ordered by symbol then date; consider only days with a full 3-day window.", ["Compute the average with `ROWS BETWEEN 2 PRECEDING AND CURRENT ROW`, then compare with `LAG` of the difference."],
  "WITH m AS (SELECT symbol, trade_date, close, AVG(close) OVER (PARTITION BY symbol ORDER BY trade_date ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS ma, COUNT(*) OVER (PARTITION BY symbol ORDER BY trade_date ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS n FROM prices), d AS (SELECT *, close - ma AS diff, LAG(close - ma) OVER (PARTITION BY symbol ORDER BY trade_date) AS prev_diff FROM m WHERE n = 3) SELECT symbol, trade_date FROM d WHERE diff > 0 AND prev_diff < 0 ORDER BY symbol, trade_date;", ordered=True)
p("Longest winning streak per ticker", "H", "gaps-islands", "For each ticker find the longest run of consecutive trading days where close was higher than the previous day's close. Show symbol and streak length, ordered by length (desc) then symbol.", ["Flag up days, then group runs with a running count of non-up days."],
  "WITH u AS (SELECT symbol, trade_date, CASE WHEN close > LAG(close) OVER (PARTITION BY symbol ORDER BY trade_date) THEN 1 ELSE 0 END AS up FROM prices), g AS (SELECT *, SUM(1 - up) OVER (PARTITION BY symbol ORDER BY trade_date) AS grp FROM u), s AS (SELECT symbol, grp, SUM(up) AS len FROM g GROUP BY symbol, grp) SELECT symbol, MAX(len) AS streak FROM s GROUP BY symbol ORDER BY streak DESC, symbol;", ordered=True)
p("Sector share of volume per week", "H", "window-functions", "For the week starting 2024-03-04 through 2024-03-08, show each sector's share of the total traded volume that week (percentage, 1 decimal), biggest share first.", ["Join tickers, filter dates, divide by the overall sum with a window."],
  "SELECT t.sector, ROUND(100.0 * SUM(p.volume) / SUM(SUM(p.volume)) OVER (), 1) AS share_pct FROM prices p JOIN tickers t ON t.symbol = p.symbol WHERE p.trade_date BETWEEN '2024-03-04' AND '2024-03-08' GROUP BY t.sector ORDER BY share_pct DESC, t.sector;", ordered=True)
p("Tickers that beat their sector average", "H", "correlated-subquery", "List tickers whose total return (last close vs first close, in percent, 2 decimals) beat the average total return of tickers in the same sector. Show symbol, sector, return_pct.", ["Compute return per ticker first, then window `AVG` per sector."],
  "WITH f AS (SELECT symbol, FIRST_VALUE(close) OVER (PARTITION BY symbol ORDER BY trade_date) AS first_close, FIRST_VALUE(close) OVER (PARTITION BY symbol ORDER BY trade_date DESC) AS last_close FROM prices), r AS (SELECT DISTINCT symbol, 100.0 * (last_close - first_close) / first_close AS ret FROM f), j AS (SELECT r.symbol, t.sector, r.ret, AVG(r.ret) OVER (PARTITION BY t.sector) AS sector_avg FROM r JOIN tickers t ON t.symbol = r.symbol) SELECT symbol, sector, ROUND(ret, 2) AS return_pct FROM j WHERE ret > sector_avg;")

B.p("Accounts with a balance dip below zero", "H", "running-total", "Treat deposits as positive and withdrawals/purchases/fees as negative amounts (the `amount` column is already signed). For each account find the lowest running balance over time and show accounts whose lowest running balance is below 0: account_id, lowest.", ["Running `SUM(amount)` ordered by date then id, then `MIN` per account."],
  "WITH r AS (SELECT account_id, SUM(amount) OVER (PARTITION BY account_id ORDER BY tx_date, id) AS bal FROM transactions) SELECT account_id, ROUND(MIN(bal), 2) AS lowest FROM r GROUP BY account_id HAVING MIN(bal) < 0;")
B.p("Customers with all three account types", "M", "having", "Which customers hold all three account types (savings, checking, credit)? Show name.", ["Count distinct account types per customer."],
  "SELECT c.name FROM customers c JOIN accounts a ON a.customer_id = c.id GROUP BY c.id HAVING COUNT(DISTINCT a.type) = 3;")
B.p("Biggest merchant per city", "H", "ranking", "For each city find the merchant with the highest total purchase spend (purchases are negative amounts; use absolute values). Show city, merchant, spend rounded to 2 decimals.", ["Join up to customers, group by city and merchant, rank within city."],
  "WITH s AS (SELECT c.city, t.merchant, SUM(-t.amount) AS spend FROM transactions t JOIN accounts a ON a.id = t.account_id JOIN customers c ON c.id = a.customer_id WHERE t.kind = 'purchase' GROUP BY c.city, t.merchant), r AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY spend DESC, merchant) AS rn FROM s) SELECT city, merchant, ROUND(spend, 2) AS spend FROM r WHERE rn = 1;")
B.p("Month-over-month deposit growth", "H", "window-functions", "Total deposits per month and the percentage change from the previous month (1 decimal; NULL for the first month). Show month (YYYY-MM), total, growth_pct.", ["Aggregate by `substr(tx_date,1,7)`, then `LAG`."],
  "WITH m AS (SELECT substr(tx_date, 1, 7) AS month, SUM(amount) AS total FROM transactions WHERE kind = 'deposit' GROUP BY 1) SELECT month, ROUND(total, 2) AS total, ROUND(100.0 * (total - LAG(total) OVER (ORDER BY month)) / LAG(total) OVER (ORDER BY month), 1) AS growth_pct FROM m ORDER BY month;", ordered=True)
B.p("Customers quiet since mid June", "M", "exists", "List customers who have accounts but none of their accounts has a transaction dated on or after 2024-06-20. Show name.", ["`NOT EXISTS` over accounts and transactions."],
  "SELECT c.name FROM customers c WHERE EXISTS (SELECT 1 FROM accounts a WHERE a.customer_id = c.id) AND NOT EXISTS (SELECT 1 FROM accounts a JOIN transactions t ON t.account_id = a.id WHERE a.customer_id = c.id AND t.tx_date >= '2024-06-20');")

E.p("Each shopper's second purchase date", "H", "window-functions", "Show each customer's second order (by date, then id): customer_id, order_id, order_date. Customers with fewer than two orders are omitted.", ["`ROW_NUMBER()` per customer."],
  "WITH r AS (SELECT customer_id, id AS order_id, order_date, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY order_date, id) AS rn FROM orders) SELECT customer_id, order_id, order_date FROM r WHERE rn = 2;")
E.p("Products never ordered together", "H", "exists", "Count product pairs (a.id < b.id) that never appear in the same order, as a single number `unpaired`.", ["All pairs minus pairs that co-occur; or `NOT EXISTS`."],
  "SELECT COUNT(*) AS unpaired FROM products a JOIN products b ON a.id < b.id WHERE NOT EXISTS (SELECT 1 FROM order_items x JOIN order_items y ON y.order_id = x.order_id WHERE x.product_id = a.id AND y.product_id = b.id);")
E.p("Cumulative share of revenue by product", "H", "running-total", "Rank products by revenue (quantity * unit_price over non-cancelled orders), highest first, and show the cumulative percentage of total revenue (1 decimal). Show product name, revenue and cum_pct, with name as tie-break.", ["Window `SUM` over a window `SUM`, ordered by revenue desc."],
  "WITH r AS (SELECT p.name, SUM(oi.quantity * oi.unit_price) AS revenue FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id WHERE o.status <> 'cancelled' GROUP BY p.id) SELECT name, ROUND(revenue, 2) AS revenue, ROUND(100.0 * SUM(revenue) OVER (ORDER BY revenue DESC, name) / SUM(revenue) OVER (), 1) AS cum_pct FROM r ORDER BY revenue DESC, name;", ordered=True)
E.p("Customers whose latest order beat their first", "H", "window-functions", "Among customers with at least 2 non-cancelled orders, list those whose latest order total (by date, then id) is larger than their first order total. Show customer name.", ["`FIRST_VALUE` with ascending and descending windows over order totals."],
  "WITH t AS (SELECT o.customer_id, o.id, o.order_date, SUM(oi.quantity * oi.unit_price) AS total FROM orders o JOIN order_items oi ON oi.order_id = o.id WHERE o.status <> 'cancelled' GROUP BY o.id), r AS (SELECT *, FIRST_VALUE(total) OVER (PARTITION BY customer_id ORDER BY order_date, id) AS first_total, FIRST_VALUE(total) OVER (PARTITION BY customer_id ORDER BY order_date DESC, id DESC) AS last_total, COUNT(*) OVER (PARTITION BY customer_id) AS n FROM t) SELECT DISTINCT c.name FROM r JOIN customers c ON c.id = r.customer_id WHERE n >= 2 AND last_total > first_total;")

M.p("Directors whose every movie beat 7 average", "H", "having", "Directors whose every movie has an average review rating above 7. Show name (only movies with reviews count).", ["Average per movie, then `MIN` of that per director."],
  "WITH a AS (SELECT m.director_id, AVG(r.rating) AS avg_r FROM movies m JOIN reviews r ON r.movie_id = m.id GROUP BY m.id) SELECT d.name FROM a JOIN directors d ON d.id = a.director_id GROUP BY a.director_id HAVING MIN(avg_r) > 7;", allow_empty=True)
M.p("Rating spread per genre", "M", "aggregate", "For each genre show the lowest and highest single review rating and the spread between them, widest spread first, ties by genre.", ["Join movies to reviews and group by genre."],
  "SELECT m.genre, MIN(r.rating) AS lowest, MAX(r.rating) AS highest, MAX(r.rating) - MIN(r.rating) AS spread FROM movies m JOIN reviews r ON r.movie_id = m.id GROUP BY m.genre ORDER BY spread DESC, m.genre;", ordered=True)
M.p("Most profitable movie per decade", "H", "ranking", "For each decade of release show the movie with the highest profit (gross minus budget). Show decade, title, profit. Ignore movies missing budget or gross.", ["Rank by profit within `release_year / 10 * 10`."],
  "WITH r AS (SELECT release_year / 10 * 10 AS decade, title, gross_millions - budget_millions AS profit, ROW_NUMBER() OVER (PARTITION BY release_year / 10 * 10 ORDER BY gross_millions - budget_millions DESC, title) AS rn FROM movies WHERE budget_millions IS NOT NULL AND gross_millions IS NOT NULL) SELECT decade, title, ROUND(profit, 1) AS profit FROM r WHERE rn = 1;")
M.p("Reviewers who rated above movie average", "H", "correlated-subquery", "Count, per reviewer, how many of their reviews were above the average rating of the movie they reviewed. Show reviewers with at least 2 such reviews, ordered by count desc then name.", ["Correlated subquery for the movie average."],
  "SELECT r.reviewer, COUNT(*) AS above FROM reviews r WHERE r.rating > (SELECT AVG(r2.rating) FROM reviews r2 WHERE r2.movie_id = r.movie_id) GROUP BY r.reviewer HAVING COUNT(*) >= 2 ORDER BY above DESC, r.reviewer;", ordered=True)
M.p("Directors releasing within two years", "H", "self-join", "Directors who released two movies at most two calendar years apart (the second one 1 or 2 years after the first). Show name and the earliest such first release year as first_year.", ["Self-join movies on the same director with `b.release_year BETWEEN a.release_year + 1 AND a.release_year + 2`."],
  "SELECT d.name, MIN(a.release_year) AS first_year FROM movies a JOIN movies b ON b.director_id = a.director_id AND b.release_year BETWEEN a.release_year + 1 AND a.release_year + 2 JOIN directors d ON d.id = a.director_id GROUP BY d.id;")
M.p("Movies per genre count", "E", "group-by", "How many movies are there in each genre? Most first, ties by genre.", ["`GROUP BY genre`."],
  "SELECT genre, COUNT(*) AS movies FROM movies GROUP BY genre ORDER BY movies DESC, genre;", ordered=True)

# register the extra sets with the builder
EXTRA = [B, E, M]
